  entries: readonly SearchableEntry[];
  query: string;
  limit?: number;
}): SearchableEntry[] => {
  const normalized = normalize(query);
  if (normalized === "") return [];
  return entries
    .flatMap((entry) => {
      const match = matches(entry, normalized);
      return match ? [{ entry, tier: match.tier }] : [];
    })
    .sort(compare)
    .slice(0, limit)
    .map(({ entry }) => entry);
};
